import{bearing}from './prayers.js';
import{mapPoint,qiblaMapRay}from './qibla-map-core.js';
import{getDevicePosition}from './city-location.js';
let library;
async function leaflet(){
 if(!document.getElementById('qibla-map-style')){const css=document.createElement('link');css.id='qibla-map-style';css.rel='stylesheet';css.href=new URL('./vendor/leaflet/leaflet.css',import.meta.url).href;document.head.append(css);}
 if(!library)library=import('./vendor/leaflet/leaflet.js').catch(error=>{library=null;throw error;});await library;return window.L;
}
export function qiblaMapMarkup(){return '<div class="qibla-map-heading"><strong>Кибла на карте</strong><span>Север ↑</span></div><p class="qibla-map-help">Приблизьте дом и коснитесь нужной точки — золотая линия укажет Киблу.</p><div id="qibla-map-canvas" class="qibla-map-canvas" role="region" aria-label="Карта местности и направление Киблы"></div><div class="qibla-map-actions"><button type="button" class="button secondary" id="qibla-map-locate" aria-label="Определить моё местоположение">Моё место</button><button type="button" class="button secondary" id="qibla-map-city" aria-label="К выбранному городу">К городу</button></div><p id="qibla-map-status" role="status" aria-live="polite">Открываем карту…</p><p class="qibla-map-privacy">Карта — OpenStreetMap. Сервис получает сетевой адрес и область просмотра. Определение места — только по кнопке; выбранная точка не сохраняется и не меняет город намазов.</p>';}
export function mountQiblaMap(host,{city,loadLibrary=leaflet,getPosition=getDevicePosition}={}){
 host.innerHTML=qiblaMapMarkup();let closed=false,map=null,leafletApi=null,point=city&&mapPoint(city.latitude,city.longitude),label=city?.name||'Выбранная точка',marker=null,ray=null,arrow=null,accuracy=null,locating=null,request=0,hadTileError=false;
 const canvas=host.querySelector('#qibla-map-canvas'),status=host.querySelector('#qibla-map-status'),locate=host.querySelector('#qibla-map-locate'),back=host.querySelector('#qibla-map-city');back.disabled=!point;
 function update(){if(closed||!map||!point)return;const heading=bearing(point.latitude,point.longitude),angle=Number.isFinite(heading)?Math.round(heading)%360:null,centre=[point.latitude,point.longitude];
  if(marker)map.removeLayer(marker);if(ray)map.removeLayer(ray);if(arrow)map.removeLayer(arrow);const L=leafletApi;
  marker=L.circleMarker(centre,{radius:7,color:'#fff5d7',weight:3,fillColor:'#ae873c',fillOpacity:1}).addTo(map);
  if(angle!==null){const bounds=map.getBounds(),edge=[bounds.getNorth(),bounds.getEast()],radius=Math.max(50,Math.min(3000000,map.distance(map.getCenter(),edge)*.9)),points=qiblaMapRay(point.latitude,point.longitude,heading,radius);ray=L.layerGroup([L.polyline(points,{color:'#17243b',weight:7,opacity:.95,interactive:false}),L.polyline(points,{color:'#dcc58e',weight:3,opacity:1,interactive:false})]).addTo(map);const end=points[points.length-1];arrow=L.marker(end,{interactive:false,keyboard:false,icon:L.divIcon({className:'qibla-map-direction',html:'<span aria-hidden="true" style="transform:rotate('+heading+'deg)">▲</span>',iconSize:[34,34],iconAnchor:[17,17]})}).addTo(map);}
  status.textContent=label+' · '+(angle===null?'Направление для этой точки не определено':angle+'° от севера')+(hadTileError?' · Подложка карты загружается не полностью.':'');
 }
 // All point selection is transient: no writes to city, history, account or analytics.
 loadLibrary().then(L=>{if(closed||!canvas.isConnected)return;if(!L)throw Error();leafletApi=L;map=L.map(canvas,{zoomControl:false,attributionControl:true,worldCopyJump:true}).setView(point?[point.latitude,point.longitude]:[25,35],point?13:3);L.control.zoom({position:'topleft',zoomInTitle:'Приблизить карту',zoomOutTitle:'Отдалить карту'}).addTo(map);
  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,minZoom:2,keepBuffer:0,updateWhenIdle:true,updateWhenZooming:false,referrerPolicy:'origin',attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).on('tileerror',()=>{hadTileError=true;if(point)update();else status.textContent='Не удалось загрузить карту. Проверьте интернет.';}).addTo(map);
  map.on('click',e=>{const next=mapPoint(e.latlng.lat,e.latlng.lng);if(!next)return;request++;locating?.abort();locating=null;locate.disabled=false;if(accuracy){map.removeLayer(accuracy);accuracy=null;}point=next;label='Выбранная точка';update();});map.on('zoomend moveend',update);update();if(!point)status.textContent='Выберите точку на карте или нажмите «Моё местоположение».';
 }).catch(()=>{if(!closed)status.textContent='Карта недоступна. Проверьте интернет и откройте её ещё раз.';});
 locate.onclick=async()=>{if(!map||closed||locating)return;const id=++request;locating=new AbortController();locate.disabled=true;status.textContent='Определяем ваше местоположение…';try{
 const position=await getPosition({signal:locating.signal,geolocation:{getCurrentPosition:(ok,fail,options)=>navigator.geolocation.getCurrentPosition(ok,fail,{...options,enableHighAccuracy:true,maximumAge:0})}});if(closed||id!==request)return;const next=mapPoint(position.coords.latitude,position.coords.longitude);if(!next)throw Error();point=next;const metres=position.coords.accuracy;label='Ваше местоположение'+(Number.isFinite(metres)?' · точность ±'+Math.round(metres)+' м':'');if(accuracy)map.removeLayer(accuracy);if(Number.isFinite(metres)&&metres>0)accuracy=leafletApi.circle([point.latitude,point.longitude],{radius:metres,color:'#287bbe',weight:1,fillOpacity:.1}).addTo(map);map.setView([point.latitude,point.longitude],Math.min(18,metres>300?14:17));update();
 }catch(error){if(!closed&&id===request)status.textContent=error?.code===1?'Доступ к местоположению закрыт. Можно выбрать дом касанием карты.':'Не удалось определить место. Выберите дом касанием карты.';}finally{if(id===request){locating=null;locate.disabled=false;}}};
 back.onclick=()=>{const next=city&&mapPoint(city.latitude,city.longitude);if(!map||!next)return;request++;locating?.abort();locating=null;locate.disabled=false;if(accuracy){map.removeLayer(accuracy);accuracy=null;}point=next;label=city.name;map.setView([point.latitude,point.longitude],13);update();};
 return{resize(){if(!closed&&map){map.invalidateSize();update();}},destroy(){closed=true;request++;locating?.abort();map?.remove();map=null;}};
}
